using Godot;
using System;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ActorAnimationTrackOperations:RefCounted
{
    private readonly ActorDataOperations _data=new();
    private static Resource New(string file)=>file switch{"actor_keyframe"=>new ActorKeyframe(),"actor_animation_track"=>new ActorAnimationTrack(),_=>throw new ArgumentException("Unknown animation resource: "+file)};
    public void sort_keys(Resource track){var keys=track.Get("keys").AsGodotArray();var ordered=new List<Resource>();foreach(var value in keys)ordered.Add(value.As<Resource>());ordered.Sort((a,b)=>a.Get("time").AsDouble().CompareTo(b.Get("time").AsDouble()));keys.Clear();foreach(var value in ordered)keys.Add(value);}
    public Resource? key_at(Resource track,double time){foreach(var value in track.Get("keys").AsGodotArray()){var key=value.As<Resource>();if(Math.Abs(key.Get("time").AsDouble()-time)<.00001)return key;}return null;}
    public bool is_state_track(Resource track){var path=track.Get("path").AsStringArray();return path.Length==2&&path[0]=="component_states";}
    private static double Weight(Resource left,double weight){var curve=left.Get("value_curve").As<Curve>();return curve!=null?curve.Sample((float)weight):left.Get("interpolation").AsInt32()==1?Mathf.Ease(weight,left.Get("attenuation").AsDouble()):weight;}
    public Variant sample(Resource track,double time,Variant fallback)
    {
        if(is_state_track(track))return transition_at(track,time,fallback)["from"];var keys=track.Get("keys").AsGodotArray();if(keys.Count==0)return fallback;var first=keys[0].As<Resource>();if(time<=first.Get("time").AsDouble())return first.Get("value");for(int i=1;i<keys.Count;i++){var right=keys[i].As<Resource>();var left=keys[i-1].As<Resource>();double rightTime=right.Get("time").AsDouble();if(time>rightTime)continue;var a=left.Get("value");var b=right.Get("value");if(time==rightTime)return b;bool text=a.VariantType is Variant.Type.String or Variant.Type.StringName;if((left.Get("interpolation").AsInt32()==2&&!text)||a.VariantType!=b.VariantType)return a;double weight=Weight(left,(time-left.Get("time").AsDouble())/Math.Max(.000001,rightTime-left.Get("time").AsDouble()));float amount=(float)weight;switch(a.VariantType){case Variant.Type.String:case Variant.Type.StringName:string value=interpolate_text(a.AsString(),b.AsString(),weight);return a.VariantType==Variant.Type.StringName?Variant.From(new StringName(value)):Variant.From(value);case Variant.Type.Float:return Mathf.Lerp(a.AsDouble(),b.AsDouble(),weight);case Variant.Type.Int:return (long)Mathf.Round(Mathf.Lerp(a.AsDouble(),b.AsDouble(),weight));case Variant.Type.Vector2:return a.AsVector2().Lerp(b.AsVector2(),amount);case Variant.Type.Vector3:var path=track.Get("path").AsStringArray();if(path.Length==3&&path[0]=="bone_poses"&&path[2]=="rotation")return Quaternion.FromEuler(a.AsVector3()*(Mathf.Pi/180)).Slerp(Quaternion.FromEuler(b.AsVector3()*(Mathf.Pi/180)),amount).GetEuler()*(180/Mathf.Pi);return a.AsVector3().Lerp(b.AsVector3(),amount);case Variant.Type.Vector4:return a.AsVector4().Lerp(b.AsVector4(),amount);case Variant.Type.Color:return a.AsColor().Lerp(b.AsColor(),amount);case Variant.Type.Vector2I:var v2=a.AsVector2I();var r2=b.AsVector2I();for(int axis=0;axis<2;axis++)v2[axis]=Mathf.RoundToInt(Mathf.Lerp((double)v2[axis],r2[axis],weight));return v2;case Variant.Type.Vector3I:var v3=a.AsVector3I();var r3=b.AsVector3I();for(int axis=0;axis<3;axis++)v3[axis]=Mathf.RoundToInt(Mathf.Lerp((double)v3[axis],r3[axis],weight));return v3;case Variant.Type.Vector4I:var v4=a.AsVector4I();var r4=b.AsVector4I();for(int axis=0;axis<4;axis++)v4[axis]=Mathf.RoundToInt(Mathf.Lerp((double)v4[axis],r4[axis],weight));return v4;default:return a;}}return keys[keys.Count-1].As<Resource>().Get("value");
    }
    public Settings transition_at(Resource track,double time,Variant fallback)
    {
        var keys=track.Get("keys").AsGodotArray();if(keys.Count==0)return new Settings{["from"]=fallback,["to"]=fallback,["weight"]=0.0,["key"]=default(Variant)};var left=keys[0].As<Resource>();foreach(var value in keys){var right=value.As<Resource>();if(time<right.Get("time").AsDouble()){if(right==left)break;double weight=Math.Clamp((time-left.Get("time").AsDouble())/Math.Max(.000001,right.Get("time").AsDouble()-left.Get("time").AsDouble()),0,1);weight=left.Get("interpolation").AsInt32()==2?0:Weight(left,weight);return new Settings{["from"]=left.Get("value"),["to"]=right.Get("value"),["weight"]=weight,["key"]=left};}left=right;}return new Settings{["from"]=left.Get("value"),["to"]=left.Get("value"),["weight"]=0.0,["key"]=left};
    }
    public string interpolate_text(string left,string right,double weight)
    {
        var a=left.EnumerateRunes().ToArray();var b=right.EnumerateRunes().ToArray();int prefix=0;while(prefix<Math.Min(a.Length,b.Length)&&a[prefix]==b[prefix])prefix++;int deleted=a.Length-prefix,added=b.Length-prefix,progress=(int)Math.Floor(Math.Clamp(weight,0,1)*(deleted+added)+.000001);var text=new StringBuilder();var source=progress<=deleted?a:b;int count=progress<=deleted?a.Length-progress:prefix+progress-deleted;for(int i=0;i<count;i++)text.Append(source[i].ToString());return text.ToString();
    }
    public Resource copy_key(Resource key){var result=New("actor_keyframe");foreach(string field in new[]{"id","time","interpolation","attenuation","curve_template","curve_adjustment"})result.Set(field,key.Get(field));result.Set("value",_data.copy_value(key.Get("value")));var curve=key.Get("value_curve").As<Curve>();result.Set("value_curve",curve!=null?Variant.From(curve.Duplicate()):default);return result;}
    public Resource copy_track(Resource track){var result=New("actor_animation_track");result.Set("path",track.Get("path").AsStringArray());result.Set("label",track.Get("label"));result.Set("component",track.Get("component"));result.Set("component_base",_data.copy_value(track.Get("component_base")));var keys=result.Get("keys").AsGodotArray();foreach(var value in track.Get("keys").AsGodotArray())keys.Add(copy_key(value.As<Resource>()));return result;}
}
